const trajectoryMap = {
    "slow circular orbit": 0, "wide oval sweep": 1, "pendulum sway": 2,
    "figure eight loop": 3, "lissajous knot": 4, "hyperbolic drift": 5, "erratic quantum hop": 6
};
const densityMap = {
    "sparse pillars": 8, "scattered monoliths": 14, "interlocking lattices": 22,
    "nested polyhedra": 30, "dense brutalist forest": 40, "labyrinthine maze": 55
};
const styleMap = {
    "rounded monoliths": 0, "chiseled prisms": 1, "faceted crystals": 2,
    "slender needle spires": 3, "segmented rings": 4, "fractured polyhedra": 5
};
const scatterMap = {
    "clean sharp shafts": 0, "soft diffused glow": 1, "luminous mist": 2,
    "drifting amber embers": 3, "swirling ash cloud": 4, "blinding radiant flare": 5
};
const paletteMap = {
    "dawn silver mist": {c: [200, 220, 255], a: 0.85},
    "cathedral amber gold": {c: [255, 180, 50], a: 0.95},
    "incandescent solar white": {c: [255, 255, 255], a: 1.0},
    "twilight amethyst violet": {c: [180, 100, 255], a: 0.9},
    "dusk copper crimson": {c: [255, 70, 25], a: 0.95},
    "deep obsidian emerald": {c: [50, 255, 120], a: 0.8}
};

let prevDensity = null;
let prevStyle = null;

let shapes = [];
let particles = [];
let lightLayer;
let errX = 400, errY = 400;

p.setup = function() {
    p.createCanvas(800, 800);
    p.noStroke();
    lightLayer = p.createGraphics(400, 400);
    lightLayer.noStroke();
    for(let i=0; i<100; i++) particles.push({x:0, y:0, vx:0, vy:0, life:0, maxLife:1});
};

function buildShapes(dStr, sStr) {
    let count = densityMap[dStr];
    let style = styleMap[sStr];
    shapes = [];
    p.randomSeed(42); 

    let targetArea = 180000 / count;
    let baseR = Math.sqrt(targetArea / Math.PI);

    for(let i=0; i<count; i++) {
        let cx = p.random(50, 750);
        let cy = p.random(50, 750);
        let r = p.random(0.7, 1.3) * baseR;
        let poly = [];
        let sides = 3;

        if (style === 0) sides = 12; 
        else if (style === 1) sides = 3; 
        else if (style === 2) sides = 6; 
        else if (style === 3) { sides = 4; r *= 0.6; } 
        else if (style === 4) sides = 10; 
        else if (style === 5) sides = p.floor(p.random(5, 8));

        let rot = p.random(p.TWO_PI);
        for(let j=0; j<sides; j++) {
            let ang = rot + j * p.TWO_PI / sides;
            let rad = r;
            if (style === 5) rad *= p.random(0.6, 1.4);
            if (style === 3 && (j===0 || j===2)) rad *= 3.5; 
            if (style === 4 && j%2===0) rad *= 0.5; 
            poly.push({x: cx + p.cos(ang)*rad, y: cy + p.sin(ang)*rad});
        }
        shapes.push({poly: poly, cx: cx, cy: cy, rotDir: p.random(-0.015, 0.015)});
    }
}

p.draw = function() {
    let trajStr = p.getSynthVar("sun_trajectory") || "slow circular orbit";
    let dStr = p.getSynthVar("canopy_density") || "sparse pillars";
    let sStr = p.getSynthVar("geometry_style") || "rounded monoliths";
    let scStr = p.getSynthVar("beam_scatter") || "clean sharp shafts";
    let palStr = p.getSynthVar("atmosphere_palette") || "dawn silver mist";

    if (dStr !== prevDensity || sStr !== prevStyle) {
        buildShapes(dStr, sStr);
        prevDensity = dStr; prevStyle = sStr;
    }

    let t = p.frameCount * 0.01;
    let sunX = 400, sunY = 400;
    let traj = trajectoryMap[trajStr];

    if (traj === 0) { sunX += 300*p.cos(t); sunY += 300*p.sin(t); }
    else if (traj === 1) { sunX += 350*p.cos(t); sunY += 150*p.sin(t); }
    else if (traj === 2) { sunX += 250*p.cos(t); sunY += -200 + 150*p.sin(t*2); }
    else if (traj === 3) { sunX += 300*p.sin(t); sunY += 200*p.sin(t*2); }
    else if (traj === 4) { sunX += 300*p.sin(3*t*0.5); sunY += 300*p.cos(2*t*0.5); }
    else if (traj === 5) { sunX += 350*p.sin(t*0.5); sunY += p.constrain(300*Math.tan(p.sin(t*0.5)*1.2), -350, 350); }
    else if (traj === 6) {
        if (p.frameCount % 30 === 0) { errX = p.random(180, 620); errY = p.random(180, 620); }
        sunX = p.lerp(sunX, errX, 0.15); sunY = p.lerp(sunY, errY, 0.15);
    }

    sunX = p.constrain(sunX, 180, 620);
    sunY = p.constrain(sunY, 180, 620);

    for (let sh of shapes) {
        for (let v of sh.poly) {
            let dx = v.x - sh.cx; let dy = v.y - sh.cy;
            v.x = sh.cx + dx * p.cos(sh.rotDir) - dy * p.sin(sh.rotDir);
            v.y = sh.cy + dx * p.sin(sh.rotDir) + dy * p.cos(sh.rotDir);
        }
    }

    let lCtx = lightLayer.drawingContext;
    lCtx.save();
    lCtx.scale(0.5, 0.5);
    lCtx.globalCompositeOperation = 'source-over';

    let pal = paletteMap[palStr];
    let sc = scatterMap[scStr];
    let grad = lCtx.createRadialGradient(sunX, sunY, 0, sunX, sunY, 1200);
    let core = "rgba(255,255,255,1)";
    let mid = `rgba(${pal.c[0]},${pal.c[1]},${pal.c[2]},${pal.a})`;
    let edge = `rgba(${pal.c[0]},${pal.c[1]},${pal.c[2]},0)`;

    if (sc === 0) { grad.addColorStop(0, core); grad.addColorStop(0.25, mid); grad.addColorStop(1, edge); }
    else if (sc === 5) { grad.addColorStop(0, core); grad.addColorStop(0.6, mid); grad.addColorStop(1, edge); }
    else { grad.addColorStop(0, core); grad.addColorStop(0.4, mid); grad.addColorStop(1, edge); }

    lCtx.fillStyle = grad;
    lCtx.fillRect(0, 0, 800, 800);

    lCtx.globalCompositeOperation = 'destination-out';
    lCtx.fillStyle = 'rgba(0,0,0,0.7)';
    lCtx.beginPath();
    for (let sh of shapes) {
        let pts = sh.poly;
        lCtx.moveTo(pts[0].x, pts[0].y);
        for (let i=1; i<pts.length; i++) lCtx.lineTo(pts[i].x, pts[i].y);
        lCtx.closePath();

        for (let i=0; i<pts.length; i++) {
            let v1 = pts[i];
            let v2 = pts[(i+1)%pts.length];
            let edgeX = v2.x - v1.x; let edgeY = v2.y - v1.y;
            let toLightX = sunX - v1.x; let toLightY = sunY - v1.y;
            if (edgeX * toLightY - edgeY * toLightX > 0) {
                lCtx.moveTo(v1.x, v1.y);
                lCtx.lineTo(v2.x, v2.y);
                lCtx.lineTo(v2.x + (v2.x - sunX)*15, v2.y + (v2.y - sunY)*15);
                lCtx.lineTo(v1.x + (v1.x - sunX)*15, v1.y + (v1.y - sunY)*15);
                lCtx.closePath();
            }
        }
    }
    lCtx.fill();
    lCtx.restore();

    p.background(12, 10, 15);
    p.drawingContext.globalCompositeOperation = 'lighter';
    p.image(lightLayer, 0, 0, 800, 800);

    if (sc >= 2) {
        p.fill(pal.c[0], pal.c[1], pal.c[2], 180);
        let spawnCount = (sc === 3) ? 3 : (sc === 4 ? 5 : 1);
        for(let i=0; i<particles.length; i++) {
            let pt = particles[i];
            if (pt.life <= 0 && spawnCount > 0) {
                pt.x = p.random(800); pt.y = p.random(800);
                pt.vx = p.random(-1.5, 1.5); pt.vy = p.random(-3, -1);
                pt.life = p.random(60, 160); pt.maxLife = pt.life;
                spawnCount--;
            }
            if (pt.life > 0) {
                pt.x += pt.vx; pt.y += pt.vy;
                if (sc===4) pt.vx += p.random(-0.15, 0.15); 
                pt.life--;
                p.fill(pal.c[0], pal.c[1], pal.c[2], (pt.life / pt.maxLife) * 255);
                p.ellipse(pt.x, pt.y, (sc===3)?3.5:2, (sc===3)?3.5:2);
            }
        }
    }

    let dCtx = p.drawingContext;
    dCtx.globalCompositeOperation = 'source-over';
    dCtx.fillStyle = '#000000';
    dCtx.strokeStyle = `rgba(${pal.c[0]},${pal.c[1]},${pal.c[2]},0.4)`;
    dCtx.lineWidth = 1.5;

    dCtx.beginPath();
    for (let sh of shapes) {
        let pts = sh.poly;
        dCtx.moveTo(pts[0].x, pts[0].y);
        for (let i=1; i<pts.length; i++) dCtx.lineTo(pts[i].x, pts[i].y);
        dCtx.closePath();
    }
    dCtx.fill();
    dCtx.stroke();
};
